   279	/** @brief 旋转的实际实现（公开入口只负责计时探针，测完删）。 */
   280	static bool myvendor_epic_rotate_impl(const uint16_t * src_buf,
   281	  uint32_t src_stride, int32_t src_w, int32_t src_h, uint16_t * dst_buf,
   282	  uint32_t dst_stride, int32_t dst_w, int32_t dst_h, int32_t angle10,
   283	  int32_t pivot_x, int32_t pivot_y, int32_t dst_cx, int32_t dst_cy);
   284	
   285	/**
   286	 * @brief RGB565 整层旋转：把 `src` 绕 (pivot_x, pivot_y) 转 `angle10`（0.1°）后，
   287	 *        让这个 pivot 落在 `dst` 的 (dst_cx, dst_cy)。
   288	 *
   289	 * @details 摆法照抄 LVGL 适配层（`lv_epic_setup_layers` + `lv_draw_sifli_epic_img`）：
   290	 *          bg = 目的整层，fg = 源整层 + `transform_cfg`，两者在**同一个坐标空间**里，
   291	 *          fg 的 `x_offset/y_offset` 决定"源的左上角摆在哪" ⇒ 让 pivot 落在
   292	 *          (dst_cx,dst_cy) 就是 `offset = dst_c - pivot`。pivot 按 HAL 注释是
   293	 *          "base on VideoLayer's origin"，即**源缓冲的像素坐标**。
   294	 *
   295	 * @note 同步（包装底下是 polling 版 HAL），返回时硬件已停。
   296	 * @note 源先 clean、目的按行 invalidate（PSRAM 写回缓存的前提）。
   297	 * @return true = 已执行；false = 参数越界/硬件不可用，**什么都没做**。
   298	 */
   299	bool myvendor_epic_rotate(const uint16_t * src_buf, uint32_t src_stride,
   300	  int32_t src_w, int32_t src_h, uint16_t * dst_buf, uint32_t dst_stride,
   301	  int32_t dst_w, int32_t dst_h, int32_t angle10, int32_t pivot_x,
   302	  int32_t pivot_y, int32_t dst_cx, int32_t dst_cy)
   303	{
   304	  if (!myvendor_epic_ready() || src_buf == NULL || dst_buf == NULL)
   305	    {
   306	      return false;
   307	    }
   308	
   309	  /* 【临时探针】旋转耗时统计（[vrot]，LOG_DEBUG，`ctl log all` 可见）。测完删。 */
   310	  {
   311	    static struct
   312	    {
   313	      uint32_t n;
   314	      uint32_t sum;
   315	      uint32_t max;
   316	      uint32_t win;
   317	    } pf;
   318	    uint32_t t0 = clock_systime_ticks();
   319	    bool r = myvendor_epic_rotate_impl(src_buf, src_stride, src_w, src_h,
   320	      dst_buf, dst_stride, dst_w, dst_h, angle10, pivot_x, pivot_y, dst_cx,
   321	      dst_cy);
   322	    uint32_t ms = (uint32_t)(clock_systime_ticks() - t0);
   323	    uint32_t win;
   324	
   325	    if (pf.win == 0u)
   326	      {
   327	        pf.win = clock_systime_ticks();
   328	      }
   329	    if (r)
   330	      {
   331	        pf.n++;
   332	        pf.sum += ms;
   333	        if (ms > pf.max)
   334	          {
   335	            pf.max = ms;
   336	          }
   337	      }
   338	    win = (uint32_t)(clock_systime_ticks() - pf.win);
   339	    if (win >= 2000u)
   340	      {
   341	        if (pf.n > 0u)
   342	          {
   343	            syslog(LOG_DEBUG, "[vrot] bakes n=%u avg=%ums max=%ums win=%ums",
   344	              (unsigned)pf.n, (unsigned)(pf.sum / pf.n), (unsigned)pf.max,
   345	              (unsigned)win);
   346	          }
   347	        pf.n = 0u;
   348	        pf.sum = 0u;
   349	        pf.max = 0u;
   350	        pf.win = clock_systime_ticks();
   351	      }
   352	    return r;
   353	  }
   354	}
   355	
   356	static bool myvendor_epic_rotate_impl(const uint16_t * src_buf,
   357	  uint32_t src_stride, int32_t src_w, int32_t src_h, uint16_t * dst_buf,
   358	  uint32_t dst_stride, int32_t dst_w, int32_t dst_h, int32_t angle10,
   359	  int32_t pivot_x, int32_t pivot_y, int32_t dst_cx, int32_t dst_cy)
   360	{
   361	  EPIC_LayerConfigTypeDef layers[2];
   362	  EPIC_LayerConfigTypeDef out;
   363	  bool ok;
   364	  const uint32_t wt_before = g_epic_wait_timeouts;
   365	
   366	  if (src_w <= 0 || src_h <= 0 || dst_w <= 0 || dst_h <= 0
   367	      || angle10 < 0 || angle10 >= 3600)
   368	    {
   369	      return false;
   370	    }
   371	
   372	  /* 坐标寄存器 10 bit（EPIC_COORDINATES_MAX = 1010），越界 HAL 会断言。 */
   373	  if (src_w > EPIC_COORDINATES_MAX || src_h > EPIC_COORDINATES_MAX
   374	      || dst_w > EPIC_COORDINATES_MAX || dst_h > EPIC_COORDINATES_MAX)
   375	    {
   376	      return false;
   377	    }
   378	
   379	  /* EPIC 绕过 CPU 缓存直读 PSRAM：先把源写回去。 */
   380	  lv_epic_clean_invalidate_cache_range(src_buf,
   381	    (size_t)src_stride * (size_t)src_h);
   382	
   383	  HAL_EPIC_LayerConfigInit(&layers[0]);          /* 背景 = 目的整层 */
   384	  layers[0].data = (uint8_t *)dst_buf;
   385	  layers[0].color_mode = EPIC_COLOR_RGB565;
   386	  layers[0].width = (uint16_t)dst_w;
   387	  layers[0].height = (uint16_t)dst_h;
   388	  layers[0].x_offset = 0;
   389	  layers[0].y_offset = 0;
   390	  layers[0].total_width = MYVENDOR_EPIC_PX_PER_ROW(dst_stride);
   391	
   392	  HAL_EPIC_LayerConfigInit(&layers[1]);          /* 前景 = 源整层 + 变换 */
   393	  layers[1].data = (uint8_t *)src_buf;
   394	  layers[1].color_mode = EPIC_COLOR_RGB565;
   395	  layers[1].width = (uint16_t)src_w;
   396	  layers[1].height = (uint16_t)src_h;
   397	  layers[1].x_offset = (int16_t)(dst_cx - pivot_x);
   398	  layers[1].y_offset = (int16_t)(dst_cy - pivot_y);
   399	  layers[1].total_width = MYVENDOR_EPIC_PX_PER_ROW(src_stride);
   400	  layers[1].transform_cfg.angle = (uint16_t)angle10;
   401	  layers[1].transform_cfg.pivot_x = (int16_t)pivot_x;
   402	  layers[1].transform_cfg.pivot_y = (int16_t)pivot_y;
   403	  layers[1].transform_cfg.scale_x = EPIC_INPUT_SCALE_NONE;
   404	  layers[1].transform_cfg.scale_y = EPIC_INPUT_SCALE_NONE;
   405	
   406	  memcpy(&out, &layers[0], sizeof(out));
   407	
   408	  /*
   409	   * 超时也算失败：HAL 的 `EPIC_WaitDone()` 超时只把 `g_epic_wait_timeouts` 加一、
   410	   * 仍返回 HAL_OK。照 HAL_OK 收下会把"没转完的像素"当成功 —— 调用方
   411	   * （`vmap_rot_full`）据此认为 R 已更新，屏上就会停在半张旧图。
   412	   * 本文件其它搬运路径（copy/fill）一直用 `epic_result()` 兜这件事，旋转也接上。
   413	   */
   414	  ok = epic_result(wt_before, lv_epic_blend(layers, 2, &out) == HAL_OK,
   415	    "rotate");
   416	
   417	  if (ok)
   418	    {
   419	      epic_invalidate_rect_rows(dst_buf, dst_stride, dst_w, dst_h);
   420	    }
   421	
   422	  return ok;
   423	}
