   346	/* operation: 0 clean, 1 clean+invalidate, 2 invalidate. Keep the original
   347	 * cache operations for cached/unknown memory, including unaligned boundaries.
   348	 */
   349	static void epic_cache_maintain(const void * data, uint32_t size, unsigned operation)
   350	{
   351	    if(data == NULL || size == 0) return;
   352	    bool required = lv_epic_is_cached_ram((uint32_t)(uintptr_t)data, size);
   353	#if defined(CONFIG_MYVENDOR_LVGL_BENCH)
   354	    cache_stats.requested_bytes += size;
   355	    if(!cache_filter_enabled) required = true;
   356	    if(!required) {
