   358	        cache_stats.skipped_bytes += size;
   359	    }
   360	    else if(operation == 0) cache_stats.clean_calls++;
   361	    else if(operation == 1) cache_stats.flush_calls++;
   362	    else cache_stats.invalidate_calls++;
