   797	        if(task->preferred_draw_unit_id != DRAW_UNIT_ID_SIFLI_EPIC) {
   798	            break;
   799	        }
   800	
   801	        task->state = LV_DRAW_TASK_STATE_IN_PROGRESS;
   802	        task->draw_unit = &draw_epic_unit->base_unit;
   803	
   804	        if(!_epic_queue_push(draw_epic_unit, task)) {
   805	            /* Should not happen (count checked above), but never lose a task:
   806	             * put it back to WAITING so a later dispatch can pick it up. */
   807	            task->state = LV_DRAW_TASK_STATE_WAITING;
   808	            break;
   809	        }
   810	
   811	        taken++;
   812	        task = lv_draw_get_next_available_task(layer, task, DRAW_UNIT_ID_SIFLI_EPIC);
   813	    }
   814	
   815	    if(epic_dispatch_log_cnt < 8) {
   816	        LV_LOG_WARN("EPIC dispatch[%u]: n=%d inited=%d",
   817	                    (unsigned int)epic_dispatch_log_cnt,
   818	                    (int)taken,
   819	                    draw_epic_unit->inited ? 1 : 0);
   820	        epic_dispatch_log_cnt++;
   821	    }
   822	
   823	    /* Let the render thread work (sync is sticky, a queued task cannot be lost) */
   824	    if(taken > 0 && draw_epic_unit->inited) {
   825	        lv_thread_sync_signal(&draw_epic_unit->sync);
   826	    }
   827	
   828	    return taken > 0 ? taken : LV_DRAW_UNIT_IDLE;
   829	#else
   830	    /* Mark task as in progress */
   831	    task->state = LV_DRAW_TASK_STATE_IN_PROGRESS;
   832	    task->draw_unit = &draw_epic_unit->base_unit;
   833	
   834	    draw_epic_unit->task_act = task;
   835	    /* Execute drawing immediately */
   836	    _epic_execute_drawing(draw_epic_unit);
   837	
   838	    draw_epic_unit->task_act->state = LV_DRAW_TASK_STATE_FINISHED;
   839	    draw_epic_unit->task_act = NULL;
   840	
   841	    /* Request new dispatching */
   842	    lv_draw_dispatch_request();
   843	    return 1;
   844	#endif
